"""Compile the C++-only UTF-8 catalogs; --check verifies the checked-in generated file."""
from pathlib import Path
import argparse
import json
import re
from string import Formatter

CPP = Path(__file__).resolve().parents[1]
FILES = ['en-original', 'ja', 'en-ja', 'zh-Hans-ja', 'zh-Hans-en']
STATUS_KEYS = (
    'IronSwordFound', 'SilverSwordFound', 'KnightSwordFound', 'HolySwordFound', 'SacredSwordFound',
    'IronShieldFound', 'SilverShieldFound', 'KnightShieldFound', 'HolyShieldFound', 'SacredShieldFound',
    'RedPotionFound', 'BluePotionFound', 'RedGemFound', 'BlueGemFound',
    'AltarHitPoints', 'AltarAttack', 'AltarDefense', 'ElixirUsed', 'BombUsed', 'SnowCrystalUsed', 'BattleWon',
)


def compile_catalogs():
    catalogs = [json.loads((CPP / 'locales' / (name + '.json')).read_text(encoding='utf-8')) for name in FILES]
    for c in catalogs:
        if len(c['dialogue']) != 268 or not all(isinstance(s, str) for s in c['dialogue']):
            raise ValueError(f"Incomplete dialogue: {c['id']}")
        if set(c['text']) != set(catalogs[0]['text']):
            raise ValueError(f"UI keys differ: {c['id']}")
        if set(c['status']) != set(STATUS_KEYS):
            raise ValueError(f"Incomplete status templates: {c['id']}")
        for key, template in c['status'].items():
            fields = [field for _, field, _, _ in Formatter().parse(template) if field is not None]
            if ((key != 'SnowCrystalUsed' and '0' not in fields) or
                    (key == 'BattleWon' and '2' not in fields) or
                    any(field not in ('0', '1', '2') for field in fields)):
                raise ValueError(f"Invalid status template: {c['id']}/{key}")
        if not isinstance(c.get('opening_story'), str) or not c['opening_story']:
            raise ValueError(f"Missing opening text: {c['id']}")
    # Compare the English catalog to the C++ source itself, independently of Rust.
    original = (CPP / 'src/original_constants.hpp').read_text(encoding='utf-8')
    dialogue = original.split('268> Dialogue{{', 1)[1].split('}};', 1)[0]
    strings = []
    for record in re.split(r',\s*//\s*\d+\s*\n', dialogue):
        literals = re.findall(r'"(?:[^"\\]|\\.)*"', record)
        if literals:
            strings.append(''.join(json.loads(s) for s in literals))
    if strings != catalogs[0]['dialogue']:
        raise ValueError('English baseline differs from cpp/src/original_constants.hpp')
    quote = lambda s: json.dumps(s, ensure_ascii=False)
    lines = ['// Generated by cpp/tools/compile_locales.py. Edit cpp/locales/*.json.',
             '#pragma once', '#include "tsw/dialogue_ids.hpp"', '#include <array>', '#include <string_view>', '',
             'namespace tsw::localization_data {', '// clang-format off',
             'inline constexpr std::array<std::string_view, 5> Ids{' + ', '.join(quote(c['id']) for c in catalogs) + '};',
             'inline constexpr std::array<std::string_view, 5> Labels{' + ', '.join(quote(c['label']) for c in catalogs) + '};']
    for i,c in enumerate(catalogs):
        lines.append(f'inline constexpr std::array<std::string_view, 268> Dialogue{i}{{{{')
        lines += [f'    {quote(s)}, // {j}' for j,s in enumerate(c['dialogue'])]
        lines.append('}};')
    lines += ['inline constexpr std::array Dialogues{Dialogue0, Dialogue1, Dialogue2, Dialogue3, Dialogue4};',
              'struct Entry { std::string_view source; std::array<std::string_view, 5> text; bool compose; };',
              'inline constexpr Entry Text[]{']
    exact = {}
    for i,s in enumerate(catalogs[0]['dialogue']):
        if s and s not in exact:
            exact[s] = [c['dialogue'][i] for c in catalogs]
    for s in catalogs[0]['text']:
        exact[s] = [c['text'][s] for c in catalogs]
    # Long speeches can be joined, and named items/monsters appear in generated status messages.
    # UI phrases are matched on word boundaries; user-entered names and paths bypass translation.
    for s,values in sorted(exact.items(), key=lambda kv: (-len(kv[0]), kv[0])):
        compose = len(s) >= 24 or s in catalogs[0]['text']
        lines.append('    {' + quote(s) + ', {' + ', '.join(map(quote, values)) + '}, ' + str(compose).lower() + '},')
    lines += ['};', 'struct StatusTemplate { DialogueId id; std::array<std::string_view, 5> text; };',
              'inline constexpr StatusTemplate StatusTemplates[]{']
    for key in STATUS_KEYS:
        lines.append('    {DialogueId::' + key + ', {' + ', '.join(quote(c['status'][key]) for c in catalogs) + '}},')
    lines += ['};', 'inline constexpr std::array<std::string_view, 5> Openings{' + ', '.join(quote(c['opening_story']) for c in catalogs) + '};',
              'inline constexpr std::array<std::string_view, 5> Endings{' + ', '.join(quote(c['ending_story']) for c in catalogs) + '};',
              '// clang-format on', '} // namespace tsw::localization_data', '']
    return '\n'.join(lines)


def comparison():
    catalogs = [json.loads((CPP / 'locales' / (name + '.json')).read_text(encoding='utf-8')) for name in FILES]
    lines = ['cpp_id\tjapanese_source_id\t' + '\t'.join(c['id'] for c in catalogs)]
    escape = lambda text: text.replace('\\', '\\\\').replace('\t', '\\t').replace('\r', '\\r').replace('\n', '\\n')
    for i in range(268):
        source = i if i <= 263 else 263 if i == 264 else i - 1
        lines.append(f'{i}\t{source}\t' + '\t'.join(escape(c['dialogue'][i]) for c in catalogs))
    return '\n'.join(lines) + '\n'


if __name__ == '__main__':
    p = argparse.ArgumentParser(description=__doc__)
    p.add_argument('--check', action='store_true')
    args = p.parse_args()
    output = CPP / 'src/localization_data.hpp'
    content = compile_catalogs()
    table = CPP / 'locales/dialogue-comparison.tsv'
    if args.check:
        if output.read_text(encoding='utf-8') != content:
            raise SystemExit('Localization data is stale; run cpp/tools/compile_locales.py')
        if table.read_text(encoding='utf-8') != comparison():
            raise SystemExit('Dialogue comparison is stale; run cpp/tools/compile_locales.py')
        print('All five C++ catalogs and the generated data agree')
    else:
        output.write_text(content, encoding='utf-8', newline='\n')
        table.write_text(comparison(), encoding='utf-8', newline='\n')
        print(f'Compiled five C++ catalogs into {output}')
